package com.shanjay.mart.controller;
import com.shanjay.mart.dao.UserDAO;import com.shanjay.mart.service.AuthService;import javax.servlet.*;import javax.servlet.http.*;import java.io.IOException;
public class RegisterServlet extends HttpServlet {private AuthService auth;public void init(){auth=new AuthService(new UserDAO((javax.sql.DataSource)getServletContext().getAttribute("ds")));}protected void doGet(HttpServletRequest r,HttpServletResponse s)throws ServletException,IOException{r.getRequestDispatcher("/WEB-INF/views/register.jsp").forward(r,s);}protected void doPost(HttpServletRequest r,HttpServletResponse s)throws ServletException,IOException{try{auth.register(r.getParameter("name"),r.getParameter("email"),r.getParameter("password"),r.getParameter("role"));s.sendRedirect(r.getContextPath()+"/login?registered=1");}catch(Exception e){r.setAttribute("error",e.getMessage());doGet(r,s);}}}
